What does this program print?

```cpp
#include <print>

int main() {
    int a = 5;
    int b = a;
    int& r = a;
    b += 1;
    r *= 10;
    std::println("{} {} {}", a, b, r);
}
```

What number does this program print?

```cpp
#include <print>

void f(int x) { x = x * 2; }
void g(int& x) { x = x + 3; }

int main() {
    int n = 4;
    f(n);
    g(n);
    f(n);
    std::println("{}", n);
}
```

On a platform where `unsigned int` is 32 bits (every mainstream desktop and server), what does this print?

```cpp
#include <print>

int main() {
    unsigned int u = 0;
    u -= 1;
    std::println("{}", u);
}
```

What does this program print?

```cpp
#include <print>
#include <vector>

int main() {
    std::vector<int> v{1, 2, 3};
    auto w = v;
    auto& u = v;
    w.push_back(4);
    w.push_back(6);
    u.push_back(5);
    std::println("{} {} {}", v.size(), w.size(), u.size());
}
```
